// The reuse decision is arithmetic, not vibes: similarity, rights, freshness and the
// vertical's reuse bias. Recorded as a decision so the cost saving is attributable.
const env = $('Envelope In').first().json;
const bias = env.payload?.profile?.creative?.asset_reuse_bias ?? 0.5;
const threshold = 0.9 - (bias * 0.25); // higher bias => accept looser matches
const hits = ($json.results || []).filter(h => h.similarity >= threshold);
const fatigued = hits.filter(h => (h.used_count ?? 0) >= 3 && (h.days_since_last_use ?? 99) < 30);
const usable = hits.filter(h => !fatigued.includes(h));

return [{ json: {
  decision: usable.length ? 'reuse' : 'generate',
  threshold,
  reuse_bias: bias,
  candidates: usable.slice(0, 5),
  fatigued_excluded: fatigued.length,
  rationale: usable.length
    ? `${usable.length} asset(s) above similarity ${threshold.toFixed(2)} with clean rights; reusing avoids a generation spend.`
    : `No asset above similarity ${threshold.toFixed(2)} with clean rights and no fatigue; generating fresh.`
} }];

// GENERATED telemetry emit.
const env = $('Envelope In').first().json;
return [{ json: { ...$json, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: env.trace_id, span_id: env.span_id, tenant_id: env.tenant_id,
  vertical: env.vertical, capability: "media.image.search",
  capability_version: "1.0.0", layer: "terminal",
  event: "span_end", status: "ok",
  decision_id: $json.decision?.decision_id ?? null, at: new Date().toISOString()
} } }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "media.image.search",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 0,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "media.image.search", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

